 def test_upload_failure_preserves_selection_and_shows_plain_russian_error(self):
  self.prepare_synthetic_owner()
  with sync_playwright() as pw:
   browser=pw.chromium.launch(executable_path=os.environ.get('CHROMIUM_BIN','/usr/bin/chromium'),args=['--no-sandbox']);page=self.page(browser);page.goto(self.base+'/publication-owner.php');page.get_by_label('Название',exact=True).fill('SYNTHETIC upload failure');page.get_by_role('button',name='Сохранить приватную редакцию',exact=True).click();page.get_by_role('heading',name='Добавить изображения и видео',exact=True).wait_for();page.route('**/publication-api.php?mode=owner&r=upload',lambda route:route.fulfill(status=413,content_type='text/html',body='<html>hosting body limit</html>'));field=page.get_by_label('Выбрать несколько изображений и видео',exact=True);field.set_input_files({'name':'SYNTHETIC.png','mimeType':'image/png','buffer':b'SYNTHETIC payload not uploaded'});page.get_by_role('button',name='Загрузить выбранные файлы',exact=True).click();expect(page.locator('#pub-message')).to_contain_text('Не все файлы добавлены');self.assertEqual(field.evaluate('x=>x.files.length'),1);expect(page.locator('.upload-status')).to_contain_text('Хостинг вернул неожиданный ответ');self.assertEqual(self.f.sql('SELECT COUNT(*) n FROM nd_publication_media')[0]['n'],0);page.unroute_all(behavior='wait');browser.close()
